// CryPhoneTracker - wire format shared with the Android "phonetracker" app.// Keep in sync with androidtracker/app/src/main/java/tw/bigspring/phonetracker/net/PacketCodec.kt// and androidtracker/tools/pose_monitor.py.#pragma oncenamespace Cry{namespace PhoneTracker{constexpr uint32 kPoseMagic    = 0x54443350; // 'P3DT' little endianconstexpr uint32 kControlMagic = 0x54433350; // 'P3CT' little endianconstexpr uint32 kLensMagic    = 0x534E4C50; // 'PLNS' little endianconstexpr uint16 kProtocolVersion = 1;constexpr uint16 kPosePacketSize    = 64;constexpr uint16 kControlPacketSize = 28;constexpr uint16 kLensPacketSize    = 32;//! Bits carried in SPosePacket::flags.enum EPoseFlags : uint16{	ePoseFlag_Valid          = 1, //!< ARCore reported TRACKING for this frame.	ePoseFlag_SessionResumed = 2, //!< First sample after the AR session resumed.	ePoseFlag_OriginMark     = 4, //!< The phone recentered; originEpoch was bumped.	ePoseFlag_Heartbeat      = 8, //!< Keep-alive sample sent while tracking is lost.};//! Commands understood by the phone (sent back over the same socket).enum EControlCommand : uint16{	eControlCmd_Ping    = 1,	eControlCmd_Pong    = 2,	eControlCmd_Recenter = 3,	eControlCmd_SetRate = 4,	eControlCmd_Pause   = 5,	eControlCmd_Resume  = 6,	eControlCmd_SetFocus = 7, //!< PC -> phone: autofocus result; param = focus distance in millimetres.};//! Bits carried in SLensPacket::flags.enum ELensFlags : uint16{	eLensFlag_EnableDepthOfField = 1, //!< The operator armed depth of field on the phone.	eLensFlag_EnableExposure     = 2, //!< The operator armed EV compensation on the phone.	eLensFlag_AutofocusRequest   = 4, //!< One-shot: run a centre autofocus raycast in the scene.};#pragma pack(push, 1)struct SPosePacket{	uint32 magic;	uint16 version;	uint16 flags;	uint32 seq;	uint32 originEpoch;	int64  deviceNs;   //!< System.nanoTime() on the phone when the packet was queued.	int64  frameNs;    //!< ARCore frame timestamp.	float  px, py, pz; //!< Raw ARCore position (right handed, Y up, metres).	float  qx, qy, qz, qw;	uint8  trackingState;	uint8  failureReason;	uint8  batteryPct;	uint8  appFps;};//! Lens state pushed by the phone whenever a slider moves, plus a low rate keep-alive.struct SLensPacket{	uint32 magic;	uint16 version;	uint16 flags;	uint32 seq;	float  focalLengthMm;	float  apertureFNumber;	float  focusDistanceM;	float  evCompensation;	uint32 iso;              //!< Sensor sensitivity (e.g. 400). 0 = not sent (older phone app).};struct SControlPacket{	uint32 magic;	uint16 version;	uint16 cmd;	uint32 seq;	int64  pcNs;	int32  param;	int32  reserved;};#pragma pack(pop)static_assert(sizeof(SPosePacket) == kPosePacketSize, "Pose packet layout must match the phone");static_assert(sizeof(SControlPacket) == kControlPacketSize, "Control packet layout must match the phone");static_assert(sizeof(SLensPacket) == kLensPacketSize, "Lens packet layout must match the phone");//! ARCore is right handed with +Y up and -Z forward; CRYENGINE is right handed with +Z up//! and +Y forward. Same handedness, so the axis swap alone is enough (matches pose_monitor.py).inline Vec3 ArCoreToCryPosition(const SPosePacket& packet){	return Vec3(packet.px, -packet.pz, packet.py);}inline Quat ArCoreToCryRotation(const SPosePacket& packet){	Quat rotation;	rotation.w = packet.qw;	rotation.v = Vec3(packet.qx, -packet.qz, packet.qy);	rotation.Normalize();	return rotation;}inline SControlPacket MakeControlPacket(EControlCommand cmd, uint32 seq, int64 pcNs, int32 param = 0){	SControlPacket packet;	ZeroStruct(packet);	packet.magic = kControlMagic;	packet.version = kProtocolVersion;	packet.cmd = static_cast<uint16>(cmd);	packet.seq = seq;	packet.pcNs = pcNs;	packet.param = param;	return packet;}} // namespace PhoneTracker} // namespace Cry